"""Atomically published progress and durable shard frontier."""
import json
import logging
import os
import tempfile
from pathlib import Path

log = logging.getLogger("reindex.checkpoint")
VERSION = 1


def fsync_dir(path):
    fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def fresh_state():
    return {"version": VERSION, "last_id": 0, "docs": 0, "complete": False,
            "shards": {}}


class Checkpoint:
    def __init__(self, path):
        self.path = Path(path)

    def load(self):
        try:
            data = json.loads(self.path.read_text())
        except FileNotFoundError:
            return fresh_state()
        except ValueError:
            log.warning("checkpoint %s unreadable, starting over", self.path)
            return fresh_state()
        # Old checkpoints could claim buffered or missing rows. They cannot be
        # safely resumed; migrate by rebuilding once, not by trusting last_id.
        if not isinstance(data, dict) or data.get("version") != VERSION:
            log.warning("legacy checkpoint %s: rebuilding with durable progress", self.path)
            return fresh_state()
        for key in fresh_state():
            if key not in data:
                raise ValueError("incomplete checkpoint: missing %s" % key)
        return data

    def save(self, state):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp = tempfile.mkstemp(prefix=self.path.name + ".", suffix=".tmp",
                                   dir=self.path.parent)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                json.dump(state, fh)
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp, self.path)
            fsync_dir(self.path.parent)
        finally:
            if os.path.exists(tmp):
                os.unlink(tmp)

    def clear(self):
        self.path.unlink(missing_ok=True)
        if self.path.parent.exists():
            fsync_dir(self.path.parent)
