"""JSON-lines shards, with a recoverable durable byte frontier.

The checkpoint is the commit record. Data may be appended before publication,
but a restart discards everything beyond its recorded shard lengths. Rows and
shard filenames remain compatible with the search service.
"""
import json
import os
from pathlib import Path

from reindex.checkpoint import fsync_dir

SHARD_ROWS = 1000
BUFFER_ROWS = 200


def shard_paths(index_dir):
    return sorted(Path(index_dir).glob("shard-*.jsonl"))


def iter_rows(index_dir):
    for path in shard_paths(index_dir):
        with open(path, encoding="utf-8") as fh:
            for line in fh:
                if line.strip():
                    yield json.loads(line)


def recover(index_dir, shards):
    """Roll back uncommitted appends, including partial JSON and new shards.

    This is idempotent even if recovery itself is interrupted. Never silently
    skip missing committed data: an inconsistent durable frontier is an error.
    """
    index_dir = Path(index_dir)
    index_dir.mkdir(parents=True, exist_ok=True)
    for name, size in shards.items():
        if (Path(name).name != name or not name.startswith("shard-")
                or not name.endswith(".jsonl") or not isinstance(size, int) or size < 0):
            raise ValueError("invalid shard frontier")
        path = index_dir / name
        if not path.exists() or path.stat().st_size < size:
            raise ValueError("committed shard missing or short: %s" % path)
    for path in shard_paths(index_dir):
        if path.name not in shards:
            path.unlink()
        elif path.stat().st_size != shards[path.name]:
            with open(path, "r+b") as fh:
                fh.truncate(shards[path.name])
                fh.flush()
                os.fsync(fh.fileno())
    fsync_dir(index_dir)


class ShardWriter:
    def __init__(self, index_dir, shard_rows=SHARD_ROWS, buffer_rows=BUFFER_ROWS):
        if shard_rows <= 0 or buffer_rows <= 0:
            raise ValueError("shard and buffer sizes must be positive")
        self.index_dir = Path(index_dir)
        self.index_dir.mkdir(parents=True, exist_ok=True)
        # Persist creation of the index directory before publishing a checkpoint.
        fsync_dir(self.index_dir.parent)
        self.shard_rows = shard_rows
        self.buffer_rows = buffer_rows
        self._buffer = []
        self._fh = None
        self._rows_in_shard = 0
        self._next_shard = self._first_free_shard()

    def _first_free_shard(self):
        numbers = [int(p.stem.split("-", 1)[1]) for p in shard_paths(self.index_dir)]
        return max(numbers) + 1 if numbers else 0

    @property
    def pending(self):
        return len(self._buffer)

    def reset(self):
        self.abort()
        recover(self.index_dir, {})
        self._next_shard = 0

    def add(self, row):
        self._buffer.append(row)
        if len(self._buffer) >= self.buffer_rows:
            self.flush()

    def _sync_shard(self):
        if self._fh is not None:
            self._fh.flush()
            os.fsync(self._fh.fileno())

    def flush(self):
        if not self._buffer:
            return
        for row in self._buffer:
            if self._fh is None or self._rows_in_shard >= self.shard_rows:
                self._rotate()
            self._fh.write(json.dumps(row, sort_keys=True, separators=(",", ":"),
                                      ensure_ascii=False) + "\n")
            self._rows_in_shard += 1
        self._sync_shard()
        self._buffer.clear()

    def frontier(self):
        """Make all rows durable before returning lengths for checkpointing."""
        self.flush()
        fsync_dir(self.index_dir)
        return {path.name: path.stat().st_size for path in shard_paths(self.index_dir)}

    def _rotate(self):
        self._close_shard()
        path = self.index_dir / ("shard-%05d.jsonl" % self._next_shard)
        self._fh = open(path, "x", encoding="utf-8")
        self._next_shard += 1
        self._rows_in_shard = 0

    def _close_shard(self):
        if self._fh is not None:
            self._sync_shard()
            self._fh.close()
            self._fh = None

    def close(self):
        self.flush()
        self._close_shard()
        fsync_dir(self.index_dir)

    def abort(self):
        """Discard RAM rows after a failure; recovery owns any on-disk tail."""
        self._buffer.clear()
        if self._fh is not None:
            self._fh.close()
            self._fh = None
